"""In-process breakpoint and watchpoint management (v1).

Records exist only in the service process: there is no persistence, so a
restart starts from an empty set. All public failures are reported via
:class:`BreakpointError`, whose ``code`` mirrors the documented error codes.
"""

from __future__ import annotations

import re
import threading
from urllib.parse import parse_qsl

VALID_KINDS = ("execute", "read", "write", "access")
_KIND_SET = frozenset(VALID_KINDS)
_VALID_SIZES = frozenset({1, 2, 4, 8})
_UINT32_MAX = (1 << 32) - 1

_CREATE_FIELDS = frozenset({"kind", "address", "enabled", "size"})
_REQUIRED_CREATE_FIELDS = frozenset({"kind", "address", "enabled"})
_PATCH_FIELDS = frozenset({"enabled"})

_ID_PATTERN = re.compile(r"[1-9][0-9]*\Z")


class BreakpointError(Exception):
    """Validation or lookup failure carrying the public error code/status."""

    def __init__(self, code: str, message: str, status: int = 400) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.status = status


def _object(body: object) -> dict:
    if not isinstance(body, dict):
        raise BreakpointError("invalid_request", "request body must be a JSON object")
    return body


def parse_create(body: object) -> tuple[str, int, int | None, bool]:
    """Validate a create request; field errors take precedence over duplicates."""
    fields = _object(body)

    missing = _REQUIRED_CREATE_FIELDS - fields.keys()
    if missing:
        raise BreakpointError("invalid_field", f"missing field(s): {', '.join(sorted(missing))}")
    extra = fields.keys() - _CREATE_FIELDS
    if extra:
        raise BreakpointError("invalid_field", f"unexpected field(s): {', '.join(sorted(extra))}")

    kind = fields["kind"]
    if not isinstance(kind, str) or kind not in _KIND_SET:
        raise BreakpointError("invalid_field", "kind must be one of execute, read, write or access")

    address = fields["address"]
    if isinstance(address, bool) or not isinstance(address, int) or not 0 <= address <= _UINT32_MAX:
        raise BreakpointError("invalid_field", "address must be an unsigned 32-bit integer")

    enabled = fields["enabled"]
    if not isinstance(enabled, bool):
        raise BreakpointError("invalid_field", "enabled must be a boolean")

    has_size = "size" in fields
    size: int | None = None
    if has_size:
        value = fields["size"]
        if isinstance(value, bool) or not isinstance(value, int) or value not in _VALID_SIZES:
            raise BreakpointError("invalid_field", "size must be one of 1, 2, 4 or 8")
        size = value

    if kind == "execute":
        if has_size:
            raise BreakpointError("invalid_field", "execute breakpoints must not carry size")
    else:
        if not has_size:
            raise BreakpointError("invalid_field", f"{kind} watchpoints require size")
        assert size is not None
        if address % size != 0:
            raise BreakpointError("invalid_field", f"address must be aligned to {size} bytes")

    return kind, address, size, enabled


def parse_patch(body: object) -> bool:
    """Validate a PATCH body, which may only toggle ``enabled``."""
    fields = _object(body)
    missing = _PATCH_FIELDS - fields.keys()
    if missing:
        raise BreakpointError("invalid_field", "missing field(s): enabled")
    extra = fields.keys() - _PATCH_FIELDS
    if extra:
        raise BreakpointError("invalid_field", f"unexpected field(s): {', '.join(sorted(extra))}")
    enabled = fields["enabled"]
    if not isinstance(enabled, bool):
        raise BreakpointError("invalid_field", "enabled must be a boolean")
    return enabled


def parse_list_query(query: str) -> tuple[str | None, bool | None]:
    """Parse the optional ``kind``/``enabled`` filters for GET collection."""
    kind: str | None = None
    enabled: bool | None = None
    seen: set[str] = set()
    for key, value in parse_qsl(query, keep_blank_values=True):
        if key in seen:
            raise BreakpointError("invalid_query", f"duplicate query parameter: {key}")
        seen.add(key)
        if key == "kind":
            if value not in _KIND_SET:
                raise BreakpointError("invalid_query", "kind must be one of execute, read, write or access")
            kind = value
        elif key == "enabled":
            if value not in ("true", "false"):
                raise BreakpointError("invalid_query", "enabled must be true or false")
            enabled = value == "true"
        else:
            raise BreakpointError("invalid_query", f"unknown query parameter: {key}")
    return kind, enabled


def parse_breakpoint_id(raw: str) -> int:
    """Validate a positive decimal id path segment."""
    if _ID_PATTERN.fullmatch(raw) is None:
        raise BreakpointError("invalid_breakpoint_id", "breakpoint id must be a positive decimal integer")
    return int(raw)


class BreakpointStore:
    """Thread-safe, append-only (within the process) breakpoint records."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._records: dict[int, dict[str, object]] = {}
        self._next_id = 1

    def create(self, kind: str, address: int, size: int | None, enabled: bool) -> dict[str, object]:
        with self._lock:
            for record in self._records.values():
                if (
                    record["kind"] == kind
                    and record["address"] == address
                    and record.get("size") == size
                ):
                    raise BreakpointError(
                        "duplicate_breakpoint",
                        "a breakpoint with the same kind, address and size already exists",
                        409,
                    )
            record: dict[str, object] = {
                "id": self._next_id,
                "kind": kind,
                "address": address,
                "enabled": enabled,
            }
            if size is not None:
                record["size"] = size
            self._records[self._next_id] = record
            self._next_id += 1
            return dict(record)

    def list(self, kind: str | None = None, enabled: bool | None = None) -> list[dict[str, object]]:
        # Insertion order is id order because ids only ever grow.
        with self._lock:
            return [
                dict(record)
                for record in self._records.values()
                if (kind is None or record["kind"] == kind)
                and (enabled is None or record["enabled"] == enabled)
            ]

    def update(self, record_id: int, enabled: bool) -> dict[str, object]:
        with self._lock:
            record = self._records.get(record_id)
            if record is None:
                raise BreakpointError(
                    "breakpoint_not_found", f"breakpoint {record_id} not found", 404
                )
            record["enabled"] = enabled
            return dict(record)

    def delete(self, record_id: int) -> dict[str, int]:
        with self._lock:
            if record_id not in self._records:
                raise BreakpointError(
                    "breakpoint_not_found", f"breakpoint {record_id} not found", 404
                )
            del self._records[record_id]
            return {"deleted": record_id}

"""Core service surface for ProbePoint.

The frozen baseline reports process health and exposes the v1 frame codec.
Breakpoint/watchpoint management lives in :mod:`probepoint.breakpoints`;
records are process-local and never persisted. Keep the public surface here
backward compatible.
"""

from __future__ import annotations

from . import __version__
from .backtrace import backtrace
from .breakpoints import (
    BreakpointStore,
    parse_create,
    parse_list_query,
    parse_patch,
)
from .frames import decode_frame, decode_stream, encode_frame
from .itm import decode_stream as itm_decode_stream
from .rsp import decode_command_response
from .rsp import decode_stream as rsp_decode_stream
from .rsp import encode_command
from .rsp import encode_packet
from .symbols import resolve_symbols


class Service:
    """Health reporting, frame/RSP codecs and in-process breakpoints."""

    name = "probepoint"
    version = __version__

    def __init__(self) -> None:
        self.breakpoints = BreakpointStore()

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def encode_frame(self, body: object) -> dict[str, str]:
        return encode_frame(body)

    def decode_frame(self, body: object) -> dict[str, object]:
        return decode_frame(body)

    def decode_stream(self, body: object) -> dict[str, object]:
        return decode_stream(body)

    def decode_itm_stream(self, body: object) -> dict[str, object]:
        return itm_decode_stream(body)

    def encode_rsp_packet(self, body: object) -> dict[str, str]:
        return encode_packet(body)

    def decode_rsp_stream(self, body: object) -> dict[str, object]:
        return rsp_decode_stream(body)

    def encode_rsp_command(self, body: object) -> dict[str, str]:
        return encode_command(body)

    def decode_rsp_command_response(self, body: object) -> dict[str, object]:
        return decode_command_response(body)

    def backtrace(self, body: object) -> dict[str, object]:
        return backtrace(body)

    def resolve_symbols(self, body: object) -> dict[str, object]:
        return resolve_symbols(body)

    def create_breakpoint(self, body: object) -> dict[str, object]:
        kind, address, size, enabled = parse_create(body)
        return self.breakpoints.create(kind, address, size, enabled)

    def list_breakpoints(self, query: str) -> list[dict[str, object]]:
        kind, enabled = parse_list_query(query)
        return self.breakpoints.list(kind, enabled)

    def update_breakpoint(self, record_id: int, body: object) -> dict[str, object]:
        return self.breakpoints.update(record_id, parse_patch(body))

    def delete_breakpoint(self, record_id: int) -> dict[str, int]:
        return self.breakpoints.delete(record_id)

import json
import threading
import unittest
import urllib.error
import urllib.request
from concurrent.futures import ThreadPoolExecutor

from probepoint.breakpoints import BreakpointStore
from probepoint.server import make_server

EXECUTE = {"kind": "execute", "address": 0x1000, "enabled": True}


class BreakpointHttpTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.httpd = make_server("127.0.0.1", 0)
        cls.port = cls.httpd.server_address[1]
        cls.thread = threading.Thread(target=cls.httpd.serve_forever, daemon=True)
        cls.thread.start()

    def setUp(self) -> None:
        # Records are process-local by design; give each test an empty store.
        self.httpd.RequestHandlerClass.service.breakpoints = BreakpointStore()

    @classmethod
    def tearDownClass(cls) -> None:
        cls.httpd.shutdown()
        cls.httpd.server_close()
        cls.thread.join()

    def request(self, method: str, path: str, body: object = ...) -> tuple[int, object]:
        data = None
        headers = {}
        if body is not ...:
            data = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(
            f"http://127.0.0.1:{self.port}{path}",
            data=data,
            headers=headers,
            method=method,
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, json.loads(resp.read())
        except urllib.error.HTTPError as exc:
            try:
                return exc.code, json.loads(exc.read())
            finally:
                exc.close()

    def raw_request(self, method: str, path: str, raw: bytes) -> tuple[int, object]:
        req = urllib.request.Request(
            f"http://127.0.0.1:{self.port}{path}",
            data=raw,
            headers={"Content-Type": "application/json"},
            method=method,
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, json.loads(resp.read())
        except urllib.error.HTTPError as exc:
            try:
                return exc.code, json.loads(exc.read())
            finally:
                exc.close()

    def create(self, body: object) -> tuple[int, object]:
        return self.request("POST", "/v1/breakpoints", body)

    def list(self, query: str = "") -> tuple[int, object]:
        return self.request("GET", f"/v1/breakpoints{query}")

    def patch(self, record_id: object, body: object) -> tuple[int, object]:
        return self.request("PATCH", f"/v1/breakpoints/{record_id}", body)

    def delete(self, record_id: object) -> tuple[int, object]:
        return self.request("DELETE", f"/v1/breakpoints/{record_id}")


class CreateTest(BreakpointHttpTest):
    def test_create_execute_normalized(self) -> None:
        status, body = self.create(EXECUTE)
        self.assertEqual(status, 201)
        self.assertEqual(
            body, {"id": 1, "kind": "execute", "address": 0x1000, "enabled": True}
        )
        self.assertNotIn("size", body)

    def test_create_watchpoint_normalized(self) -> None:
        status, body = self.create({"kind": "write", "address": 0x2000, "size": 4, "enabled": False})
        self.assertEqual(status, 201)
        self.assertEqual(
            body,
            {"id": 1, "kind": "write", "address": 0x2000, "size": 4, "enabled": False},
        )

    def test_address_bounds(self) -> None:
        status, _ = self.create({"kind": "execute", "address": 0xFFFFFFFF, "enabled": True})
        self.assertEqual(status, 201)

    def test_invalid_request_not_json_object(self) -> None:
        status, resp = self.raw_request("POST", "/v1/breakpoints", b"not json")
        self.assertEqual(status, 400)
        self.assertEqual(resp["error"]["code"], "invalid_request")
        for body in ([], "x", 42, None, 3.5):
            with self.subTest(body=body):
                status, resp = self.create(body)
                self.assertEqual(status, 400)
                self.assertEqual(resp["error"]["code"], "invalid_request")

    def test_field_errors(self) -> None:
        cases = [
            {},
            {"kind": "execute", "address": 0, "enabled": True, "extra": 1},
            {"kind": "bogus", "address": 0, "enabled": True},
            {"kind": 5, "address": 0, "enabled": True},
            {"kind": "execute", "address": -1, "enabled": True},
            {"kind": "execute", "address": 1 << 32, "enabled": True},
            {"kind": "execute", "address": 1.5, "enabled": True},
            {"kind": "execute", "address": "8", "enabled": True},
            {"kind": "execute", "address": 0, "enabled": 1},
            {"kind": "execute", "address": 0, "enabled": "yes"},
            {"kind": "execute", "address": 0, "enabled": True, "size": 3},
            {"kind": "execute", "address": 0, "enabled": True, "size": 0},
            {"kind": "execute", "address": 0, "enabled": True, "size": "4"},
            {"kind": "read", "address": 8, "enabled": True},
            {"kind": "write", "address": 7, "size": 4, "enabled": True},
            {"kind": "access", "address": 3, "size": 2, "enabled": True},
            {"kind": "read", "address": 8, "size": 2, "enabled": True, "x": 0},
        ]
        for body in cases:
            with self.subTest(body=body):
                status, resp = self.create(body)
                self.assertEqual(status, 400)
                self.assertEqual(resp["error"]["code"], "invalid_field")

    def test_aligned_watchpoints_accepted(self) -> None:
        for kind, size in (("read", 1), ("write", 2), ("access", 8)):
            with self.subTest(kind=kind, size=size):
                status, body = self.create(
                    {"kind": kind, "address": 0x3000 + size, "size": size, "enabled": True}
                )
                self.assertEqual(status, 201, body)

    def test_duplicate_regardless_of_enabled(self) -> None:
        status, first = self.create({"kind": "read", "address": 0x4000, "size": 4, "enabled": True})
        self.assertEqual(status, 201)
        status, resp = self.create({"kind": "read", "address": 0x4000, "size": 4, "enabled": False})
        self.assertEqual(status, 409)
        self.assertEqual(resp["error"]["code"], "duplicate_breakpoint")

    def test_same_address_different_kind_or_size_ok(self) -> None:
        base = {"kind": "write", "address": 0x5000, "size": 4, "enabled": True}
        status, _ = self.create(base)
        self.assertEqual(status, 201)
        status, _ = self.create({**base, "kind": "access"})
        self.assertEqual(status, 201)
        status, _ = self.create({**base, "size": 8, "address": 0x5000})
        self.assertEqual(status, 201)

    def test_field_validation_before_duplicate(self) -> None:
        status, _ = self.create({"kind": "write", "address": 0x6000, "size": 4, "enabled": True})
        self.assertEqual(status, 201)
        # Duplicate triad, but malformed payload -> invalid_field, not 409.
        status, resp = self.create({"kind": "write", "address": 0x6000, "enabled": True})
        self.assertEqual(status, 400)
        self.assertEqual(resp["error"]["code"], "invalid_field")


class ListTest(BreakpointHttpTest):
    def seed(self) -> None:
        seeds = [
            {"kind": "execute", "address": 0x100, "enabled": True},
            {"kind": "read", "address": 0x200, "size": 4, "enabled": False},
            {"kind": "write", "address": 0x208, "size": 8, "enabled": True},
        ]
        for body in seeds:
            status, _ = self.create(body)
            self.assertEqual(status, 201)

    def test_list_sorted_by_id(self) -> None:
        self.seed()
        status, body = self.list()
        self.assertEqual(status, 200)
        self.assertIsInstance(body, list)
        self.assertEqual([item["id"] for item in body], [1, 2, 3])

    def test_filter_by_kind(self) -> None:
        self.seed()
        status, body = self.list("?kind=read")
        self.assertEqual(status, 200)
        self.assertEqual([item["kind"] for item in body], ["read"])

    def test_filter_by_enabled(self) -> None:
        self.seed()
        status, body = self.list("?enabled=false")
        self.assertEqual(status, 200)
        self.assertEqual([item["id"] for item in body], [2])

    def test_filter_kind_and_enabled(self) -> None:
        self.seed()
        status, body = self.list("?kind=write&enabled=true")
        self.assertEqual(status, 200)
        self.assertEqual([item["id"] for item in body], [3])
        status, body = self.list("?kind=read&enabled=true")
        self.assertEqual(status, 200)
        self.assertEqual(body, [])

    def test_invalid_query(self) -> None:
        for query in (
            "?bogus=1",
            "?kind=read&kind=write",
            "?enabled=true&enabled=false",
            "?kind=nope",
            "?enabled=1",
            "?kind=",
            "?enabled=",
            "?kind=read&extra=2",
        ):
            with self.subTest(query=query):
                status, resp = self.list(query)
                self.assertEqual(status, 400)
                self.assertEqual(resp["error"]["code"], "invalid_query")


class UpdateDeleteTest(BreakpointHttpTest):
    def make_one(self) -> int:
        status, body = self.create({"kind": "write", "address": 0x7000, "size": 4, "enabled": True})
        self.assertEqual(status, 201)
        return body["id"]

    def test_patch_toggles_enabled(self) -> None:
        record_id = self.make_one()
        status, body = self.patch(record_id, {"enabled": False})
        self.assertEqual(status, 200)
        self.assertEqual(body["id"], record_id)
        self.assertFalse(body["enabled"])
        self.assertEqual(body["kind"], "write")
        self.assertEqual(body["size"], 4)

    def test_patch_field_errors(self) -> None:
        record_id = self.make_one()
        for body in ({}, {"enabled": False, "x": 1}, {"enabled": 0}, {"id": 2}):
            with self.subTest(body=body):
                status, resp = self.patch(record_id, body)
                self.assertEqual(status, 400)
                self.assertEqual(resp["error"]["code"], "invalid_field")

    def test_delete_returns_deleted(self) -> None:
        record_id = self.make_one()
        status, body = self.delete(record_id)
        self.assertEqual(status, 200)
        self.assertEqual(body, {"deleted": record_id})
        status, resp = self.delete(record_id)
        self.assertEqual(status, 404)
        self.assertEqual(resp["error"]["code"], "breakpoint_not_found")

    def test_missing_positive_id_is_not_found(self) -> None:
        status, resp = self.patch(9999, {"enabled": True})
        self.assertEqual(status, 404)
        self.assertEqual(resp["error"]["code"], "breakpoint_not_found")
        status, resp = self.delete(9999)
        self.assertEqual(status, 404)
        self.assertEqual(resp["error"]["code"], "breakpoint_not_found")

    def test_invalid_id_path(self) -> None:
        for raw in ("0", "-1", "abc", "1a", "1.5", "%201", "+1", "01"):
            for method in ("PATCH", "DELETE"):
                with self.subTest(raw=raw, method=method):
                    status, resp = self.request(method, f"/v1/breakpoints/{raw}", {"enabled": True})
                    self.assertEqual(status, 400)
                    self.assertEqual(resp["error"]["code"], "invalid_breakpoint_id")

    def test_update_and_delete_isolated(self) -> None:
        first = self.make_one()
        status, second_body = self.create(
            {"kind": "read", "address": 0x7100, "size": 1, "enabled": True}
        )
        self.assertEqual(status, 201)
        second = second_body["id"]
        self.patch(first, {"enabled": False})
        self.delete(second)
        status, body = self.list()
        self.assertEqual(status, 200)
        records = {item["id"]: item for item in body}
        self.assertFalse(records[first]["enabled"])
        self.assertNotIn(second, records)


class ConcurrencyTest(BreakpointHttpTest):
    def test_concurrent_create_ids_unique_and_contiguous(self) -> None:
        def create_one(index: int) -> tuple[int, object]:
            return self.create(
                {"kind": "write", "address": 0x8000 + index * 8, "size": 8, "enabled": True}
            )

        with ThreadPoolExecutor(max_workers=16) as pool:
            results = list(pool.map(create_one, range(64)))
        statuses = [status for status, _ in results]
        self.assertEqual(set(statuses), {201})
        ids = sorted(body["id"] for _, body in results)
        self.assertEqual(len(set(ids)), 64)
        self.assertEqual(ids, list(range(ids[0], ids[0] + 64)))

        status, body = self.list()
        self.assertEqual(status, 200)
        self.assertEqual(len(body), 64)


class RouteCompatibilityTest(BreakpointHttpTest):
    def test_healthz_unchanged(self) -> None:
        status, body = self.request("GET", "/healthz")
        self.assertEqual(status, 200)
        self.assertEqual(body["status"], "ok")

    def test_unknown_routes_still_not_found(self) -> None:
        status, resp = self.request("GET", "/nope")
        self.assertEqual(status, 404)
        self.assertEqual(resp["error"]["code"], "not_found")
        status, resp = self.request("DELETE", "/v1/breakpoints")
        self.assertEqual(status, 404)
        self.assertEqual(resp["error"]["code"], "not_found")

    def test_collection_get_rejects_post_query_style_paths(self) -> None:
        # Trailing slash is not the item resource nor the collection.
        status, resp = self.request("GET", "/v1/breakpoints/")
        self.assertEqual(status, 404)
        self.assertEqual(resp["error"]["code"], "not_found")


if __name__ == "__main__":
    unittest.main()

